//! Portable virtio-rng device over the modern virtio-mmio transport.
//!
//! The guest supplies device-writable split-virtqueue buffers. Each queue
//! notification fills those buffers directly from the host CSPRNG, completes
//! the used entries, and raises the device interrupt. Generated bytes are never
//! buffered in device state, so pause/resume and snapshot restoration cannot
//! replay an earlier entropy block.

use rand::RngCore;
use virtio_queue::desc::split::Descriptor;
use virtio_queue::{QueueOwnedT, QueueT};

use super::device_state::{
    DeviceKind, DeviceStateError, SnapshotDeviceState, StateReader, StateWriter,
};
use super::guest_mem::GuestMem;
use super::{RingGeometry, build_split_queue};

const VIRTIO_MAGIC: u32 = 0x7472_6976;
const VIRTIO_VERSION: u32 = 2;
const VIRTIO_ID_RNG: u32 = 4;
const VIRTIO_VENDOR: u32 = 0x4d56_4d76;

const R_MAGIC: u64 = 0x000;
const R_VERSION: u64 = 0x004;
const R_DEVICE_ID: u64 = 0x008;
const R_VENDOR_ID: u64 = 0x00c;
const R_DEVICE_FEATURES: u64 = 0x010;
const R_DEVICE_FEATURES_SEL: u64 = 0x014;
const R_DRIVER_FEATURES: u64 = 0x020;
const R_DRIVER_FEATURES_SEL: u64 = 0x024;
const R_QUEUE_SEL: u64 = 0x030;
const R_QUEUE_NUM_MAX: u64 = 0x034;
const R_QUEUE_NUM: u64 = 0x038;
const R_QUEUE_READY: u64 = 0x044;
const R_QUEUE_NOTIFY: u64 = 0x050;
const R_INTERRUPT_STATUS: u64 = 0x060;
const R_INTERRUPT_ACK: u64 = 0x064;
const R_STATUS: u64 = 0x070;
const R_QUEUE_DESC_LO: u64 = 0x080;
const R_QUEUE_DESC_HI: u64 = 0x084;
const R_QUEUE_DRIVER_LO: u64 = 0x090;
const R_QUEUE_DRIVER_HI: u64 = 0x094;
const R_QUEUE_DEVICE_LO: u64 = 0x0a0;
const R_QUEUE_DEVICE_HI: u64 = 0x0a4;

const MMIO_LEN: u64 = 0x200;
const FILL_CHUNK: usize = 4096;
/// A hostile guest controls descriptor lengths and available-ring depth. Keep
/// one notification bounded while remaining far above Linux hwrng's normal
/// request size.
const MAX_BYTES_PER_NOTIFICATION: usize = 1024 * 1024;

trait EntropySource {
    fn fill(&mut self, bytes: &mut [u8]) -> bool;
}

struct OsEntropy;

impl EntropySource for OsEntropy {
    fn fill(&mut self, bytes: &mut [u8]) -> bool {
        rand::rngs::OsRng.try_fill_bytes(bytes).is_ok()
    }
}

struct EntropyRequest {
    head: u16,
    destinations: Vec<(u64, usize)>,
    len: usize,
}

/// A virtio-mmio entropy device backed by the host operating system CSPRNG.
pub struct VirtioRng {
    base: u64,
    irq: u32,
    mem: GuestMem,
    entropy: Box<dyn EntropySource>,
    device_features_sel: u32,
    status: u32,
    queue_num: u32,
    queue_ready: u32,
    desc: u64,
    avail: u64,
    used: u64,
    last_avail: u16,
    next_used: u16,
    interrupt_status: u32,
}

impl VirtioRng {
    /// Create a device over externally owned guest RAM.
    ///
    /// # Safety
    ///
    /// `ram` must point to `ram_size` bytes mapped as guest RAM at `ram_base`,
    /// and that mapping must remain valid for this device's lifetime.
    pub unsafe fn new(base: u64, irq: u32, ram: *mut u8, ram_base: u64, ram_size: usize) -> Self {
        // SAFETY: forwarded from this function's contract.
        let mem = unsafe { GuestMem::new(ram, ram_base, ram_size) };
        Self::with_entropy(base, irq, mem, Box::new(OsEntropy))
    }

    fn with_entropy(base: u64, irq: u32, mem: GuestMem, entropy: Box<dyn EntropySource>) -> Self {
        Self {
            base,
            irq,
            mem,
            entropy,
            device_features_sel: 0,
            status: 0,
            queue_num: 0,
            queue_ready: 0,
            desc: 0,
            avail: 0,
            used: 0,
            last_avail: 0,
            next_used: 0,
            interrupt_status: 0,
        }
    }

    pub fn base(&self) -> u64 {
        self.base
    }

    pub fn irq(&self) -> u32 {
        self.irq
    }

    pub fn contains(&self, addr: u64) -> bool {
        addr >= self.base && addr < self.base + MMIO_LEN
    }

    /// Handle a virtio-mmio register read.
    pub fn read(&self, offset: u64) -> u64 {
        u64::from(match offset {
            R_MAGIC => VIRTIO_MAGIC,
            R_VERSION => VIRTIO_VERSION,
            R_DEVICE_ID => VIRTIO_ID_RNG,
            R_VENDOR_ID => VIRTIO_VENDOR,
            // VIRTIO_F_VERSION_1 is bit 32, exposed as bit 0 of feature page 1.
            R_DEVICE_FEATURES if self.device_features_sel == 1 => 1,
            R_DEVICE_FEATURES => 0,
            R_QUEUE_NUM_MAX => super::QUEUE_SIZE_MAX,
            R_QUEUE_READY => self.queue_ready,
            R_INTERRUPT_STATUS => self.interrupt_status,
            R_STATUS => self.status,
            _ => 0,
        })
    }

    /// Handle a virtio-mmio register write. Returns `true` when an interrupt
    /// should be raised because at least one entropy request completed.
    pub fn write(&mut self, offset: u64, value: u64) -> bool {
        let value = value as u32;
        match offset {
            R_DEVICE_FEATURES_SEL => self.device_features_sel = value,
            R_DRIVER_FEATURES_SEL | R_DRIVER_FEATURES => {}
            R_QUEUE_SEL => {}
            R_QUEUE_NUM => self.queue_num = value,
            R_QUEUE_READY => {
                self.queue_ready = value;
                if value == 0 {
                    self.rewind_ring_cursors();
                }
            }
            R_STATUS => {
                self.status = value;
                if value == 0 {
                    self.rewind_ring_cursors();
                }
            }
            R_INTERRUPT_ACK => self.interrupt_status &= !value,
            R_QUEUE_DESC_LO => set_lo(&mut self.desc, value),
            R_QUEUE_DESC_HI => set_hi(&mut self.desc, value),
            R_QUEUE_DRIVER_LO => set_lo(&mut self.avail, value),
            R_QUEUE_DRIVER_HI => set_hi(&mut self.avail, value),
            R_QUEUE_DEVICE_LO => set_lo(&mut self.used, value),
            R_QUEUE_DEVICE_HI => set_hi(&mut self.used, value),
            R_QUEUE_NOTIFY if value == 0 => return self.process_queue(),
            R_QUEUE_NOTIFY => {}
            _ => {}
        }
        false
    }

    fn process_queue(&mut self) -> bool {
        if self.queue_ready == 0 {
            return false;
        }
        let Some(queue_size) = super::validated_queue_size(self.queue_num) else {
            return false;
        };
        let Some(mem) = self.mem.guest_memory() else {
            return false;
        };
        let Some(mut queue) = build_split_queue(self.ring(), queue_size) else {
            return false;
        };

        let mut requests = Vec::new();
        let mut remaining = MAX_BYTES_PER_NOTIFICATION;
        {
            let Ok(mut available) = queue.iter(&mem) else {
                return false;
            };
            while remaining > 0 {
                let Some(chain) = available.next() else {
                    break;
                };
                let head = chain.head_index();
                let writable: Vec<Descriptor> = chain.writable().collect();
                let request = self.plan_request(head, &writable, remaining);
                remaining -= request.len;
                requests.push(request);
            }
        }

        if requests.is_empty() {
            return false;
        }
        if !self.fill_requests(&requests) {
            // A host CSPRNG failure must not publish a zero or partial entropy
            // response. Leave both device cursors untouched so a later
            // notification can retry the same available entries.
            return false;
        }
        for request in requests {
            let written = u32::try_from(request.len)
                .expect("the notification entropy limit fits in a used-ring length");
            let _ = queue.add_used(&mem, request.head, written);
        }
        self.last_avail = queue.next_avail();
        self.next_used = queue.next_used();
        self.interrupt_status |= 1;
        true
    }

    fn plan_request(&self, head: u16, writable: &[Descriptor], budget: usize) -> EntropyRequest {
        let mut remaining = budget;
        let mut destinations = Vec::new();
        let mut total = 0usize;

        for descriptor in writable {
            let Ok(descriptor_len) = usize::try_from(descriptor.len()) else {
                continue;
            };
            let requested = descriptor_len.min(remaining);
            if requested == 0 {
                break;
            }
            let address = descriptor.addr().0;
            if self.mem.host(address, requested).is_none() {
                continue;
            }
            destinations.push((address, requested));
            total += requested;
            remaining -= requested;
            if remaining == 0 {
                break;
            }
        }

        EntropyRequest {
            head,
            destinations,
            len: total,
        }
    }

    fn fill_requests(&mut self, requests: &[EntropyRequest]) -> bool {
        let total = requests.iter().map(|request| request.len).sum();
        // Acquire the complete bounded response before touching guest memory.
        // If a later host CSPRNG call fails, no partial response is observable.
        let mut generated = vec![0u8; total];
        for chunk in generated.chunks_mut(FILL_CHUNK) {
            if !self.entropy.fill(chunk) {
                return false;
            }
        }

        let mut source_offset = 0usize;
        for request in requests {
            for &(address, len) in &request.destinations {
                let end = source_offset + len;
                if self
                    .mem
                    .write_bytes(address, &generated[source_offset..end])
                    != len
                {
                    return false;
                }
                source_offset = end;
            }
        }
        true
    }

    fn ring(&self) -> RingGeometry {
        RingGeometry {
            desc: self.desc,
            avail: self.avail,
            used: self.used,
            next_avail: self.last_avail,
            next_used: self.next_used,
        }
    }

    fn rewind_ring_cursors(&mut self) {
        self.last_avail = 0;
        self.next_used = 0;
    }
}

impl SnapshotDeviceState for VirtioRng {
    fn device_kind(&self) -> DeviceKind {
        DeviceKind::VirtioRng
    }

    fn snapshot_state(&self) -> Result<Vec<u8>, DeviceStateError> {
        let mut writer = StateWriter::new(1);
        writer.u32(self.device_features_sel);
        writer.u32(self.status);
        writer.u32(self.queue_num);
        writer.u32(self.queue_ready);
        writer.u64(self.desc);
        writer.u64(self.avail);
        writer.u64(self.used);
        writer.u16(self.last_avail);
        writer.u16(self.next_used);
        writer.u32(self.interrupt_status);
        Ok(writer.finish())
    }

    fn restore_state(&mut self, bytes: &[u8]) -> Result<(), DeviceStateError> {
        let kind = DeviceKind::VirtioRng;
        let mut reader = StateReader::new(bytes);
        let version = reader.version(kind)?;
        if version != 1 {
            return Err(DeviceStateError::UnsupportedVersion(version));
        }
        let device_features_sel = reader.u32(kind, "device_features_sel")?;
        let status = reader.u32(kind, "status")?;
        let queue_num = reader.u32(kind, "queue_num")?;
        let queue_ready = reader.u32(kind, "queue_ready")?;
        let desc = reader.u64(kind, "desc")?;
        let avail = reader.u64(kind, "avail")?;
        let used = reader.u64(kind, "used")?;
        let last_avail = reader.u16(kind, "last_avail")?;
        let next_used = reader.u16(kind, "next_used")?;
        let interrupt_status = reader.u32(kind, "interrupt_status")?;
        reader.finish()?;

        if device_features_sel > 1 {
            return Err(DeviceStateError::InvalidValue {
                kind,
                field: "device_features_sel",
            });
        }
        if queue_ready > 1 {
            return Err(DeviceStateError::InvalidValue {
                kind,
                field: "queue_ready",
            });
        }
        if queue_num != 0 && super::validated_queue_size(queue_num).is_none() {
            return Err(DeviceStateError::InvalidValue {
                kind,
                field: "queue_num",
            });
        }

        self.device_features_sel = device_features_sel;
        self.status = status;
        self.queue_num = queue_num;
        self.queue_ready = queue_ready;
        self.desc = desc;
        self.avail = avail;
        self.used = used;
        self.last_avail = last_avail;
        self.next_used = next_used;
        self.interrupt_status = interrupt_status;
        Ok(())
    }
}

fn set_lo(word: &mut u64, value: u32) {
    *word = (*word & 0xffff_ffff_0000_0000) | u64::from(value);
}

fn set_hi(word: &mut u64, value: u32) {
    *word = (*word & 0x0000_0000_ffff_ffff) | (u64::from(value) << 32);
}

#[cfg(test)]
mod tests {
    use super::*;

    const RAM_BASE: u64 = 0x4000_0000;
    const RAM_SIZE: usize = 0x20_0000;
    const DEVICE_BASE: u64 = 0x0a00_0e00;
    const IRQ: u32 = 55;
    const DESC: u64 = RAM_BASE + 0x1000;
    const AVAIL: u64 = RAM_BASE + 0x2000;
    const USED: u64 = RAM_BASE + 0x3000;
    const BUFFER: u64 = RAM_BASE + 0x4000;
    const DESC_F_WRITE: u16 = 2;

    struct CountingEntropy(u8);

    impl EntropySource for CountingEntropy {
        fn fill(&mut self, bytes: &mut [u8]) -> bool {
            for byte in bytes {
                *byte = self.0;
                self.0 = self.0.wrapping_add(1);
            }
            true
        }
    }

    struct FailedEntropy;

    impl EntropySource for FailedEntropy {
        fn fill(&mut self, _bytes: &mut [u8]) -> bool {
            false
        }
    }

    struct FailAfterOneFill(bool);

    impl EntropySource for FailAfterOneFill {
        fn fill(&mut self, bytes: &mut [u8]) -> bool {
            if self.0 {
                return false;
            }
            bytes.fill(0xaa);
            self.0 = true;
            true
        }
    }

    fn device(entropy: Box<dyn EntropySource>) -> VirtioRng {
        let ram = crate::test_support::page_aligned_ram(RAM_SIZE);
        // SAFETY: the page-aligned leaked allocation remains valid for the test
        // process lifetime and is mapped at RAM_BASE in the device view.
        let mem = unsafe { GuestMem::new(ram.as_mut_ptr(), RAM_BASE, ram.len()) };
        VirtioRng::with_entropy(DEVICE_BASE, IRQ, mem, entropy)
    }

    fn write_descriptor(device: &VirtioRng, index: u64, address: u64, len: u32, flags: u16) {
        let at = DESC + index * 16;
        device.mem.write_bytes(at, &address.to_le_bytes());
        device.mem.write_bytes(at + 8, &len.to_le_bytes());
        device.mem.write_bytes(at + 12, &flags.to_le_bytes());
        device.mem.write_bytes(at + 14, &0u16.to_le_bytes());
    }

    fn configure(device: &mut VirtioRng, address: u64, len: u32, flags: u16) {
        write_descriptor(device, 0, address, len, flags);
        device.mem.wr_u16(AVAIL + 2, 1);
        device.mem.wr_u16(AVAIL + 4, 0);
        device.write(R_QUEUE_NUM, 4);
        device.write(R_QUEUE_DESC_LO, DESC);
        device.write(R_QUEUE_DRIVER_LO, AVAIL);
        device.write(R_QUEUE_DEVICE_LO, USED);
        device.write(R_QUEUE_READY, 1);
    }

    #[test]
    fn advertises_modern_virtio_rng_identity() {
        let mut device = device(Box::new(CountingEntropy(1)));
        assert_eq!(device.read(R_MAGIC), u64::from(VIRTIO_MAGIC));
        assert_eq!(device.read(R_VERSION), u64::from(VIRTIO_VERSION));
        assert_eq!(device.read(R_DEVICE_ID), u64::from(VIRTIO_ID_RNG));
        assert_eq!(device.read(R_VENDOR_ID), u64::from(VIRTIO_VENDOR));
        device.write(R_DEVICE_FEATURES_SEL, 1);
        assert_eq!(device.read(R_DEVICE_FEATURES), 1);
    }

    #[test]
    fn fills_writable_buffers_and_signals_completion() {
        let mut device = device(Box::new(CountingEntropy(1)));
        configure(&mut device, BUFFER, 32, DESC_F_WRITE);

        assert!(device.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(
            device.mem.read_bytes(BUFFER, 32),
            (1u8..=32).collect::<Vec<_>>()
        );
        assert_eq!(device.mem.rd_u16(USED + 2), 1);
        assert_eq!(device.mem.rd_u32(USED + 4), 0);
        assert_eq!(device.mem.rd_u32(USED + 8), 32);
        assert_eq!(device.read(R_INTERRUPT_STATUS), 1);
        device.write(R_INTERRUPT_ACK, 1);
        assert_eq!(device.read(R_INTERRUPT_STATUS), 0);
    }

    #[test]
    fn never_replays_generated_bytes_across_requests() {
        let mut device = device(Box::new(CountingEntropy(0)));
        configure(&mut device, BUFFER, 16, DESC_F_WRITE);
        assert!(device.write(R_QUEUE_NOTIFY, 0));
        let first = device.mem.read_bytes(BUFFER, 16);

        write_descriptor(&device, 1, BUFFER + 32, 16, DESC_F_WRITE);
        device.mem.wr_u16(AVAIL + 6, 1);
        device.mem.wr_u16(AVAIL + 2, 2);
        assert!(device.write(R_QUEUE_NOTIFY, 0));
        let second = device.mem.read_bytes(BUFFER + 32, 16);

        assert_ne!(first, second);
        assert_eq!(first, (0u8..16).collect::<Vec<_>>());
        assert_eq!(second, (16u8..32).collect::<Vec<_>>());
    }

    #[test]
    fn ignores_guest_readable_and_out_of_bounds_buffers() {
        let mut readable = device(Box::new(CountingEntropy(1)));
        configure(&mut readable, BUFFER, 32, 0);
        assert!(readable.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(readable.mem.read_bytes(BUFFER, 32), vec![0; 32]);
        assert_eq!(readable.mem.rd_u32(USED + 8), 0);

        let mut outside = device(Box::new(CountingEntropy(1)));
        configure(
            &mut outside,
            RAM_BASE + RAM_SIZE as u64 - 8,
            32,
            DESC_F_WRITE,
        );
        assert!(outside.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(outside.mem.rd_u32(USED + 8), 0);
    }

    #[test]
    fn host_entropy_failure_does_not_consume_or_complete_request() {
        let mut device = device(Box::new(FailedEntropy));
        configure(&mut device, BUFFER, 32, DESC_F_WRITE);

        assert!(!device.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(device.last_avail, 0);
        assert_eq!(device.next_used, 0);
        assert_eq!(device.mem.rd_u16(USED + 2), 0);
        assert_eq!(device.read(R_INTERRUPT_STATUS), 0);
        assert_eq!(device.mem.read_bytes(BUFFER, 32), vec![0; 32]);
    }

    #[test]
    fn entropy_failure_after_generation_begins_never_writes_guest_memory() {
        let mut device = device(Box::new(FailAfterOneFill(false)));
        configure(
            &mut device,
            BUFFER,
            u32::try_from(FILL_CHUNK + 1).unwrap(),
            DESC_F_WRITE,
        );

        assert!(!device.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(device.mem.rd_u16(USED + 2), 0);
        assert_eq!(
            device.mem.read_bytes(BUFFER, FILL_CHUNK + 1),
            vec![0; FILL_CHUNK + 1]
        );
    }

    #[test]
    fn bounds_total_entropy_work_across_all_chains_in_one_notification() {
        let mut device = device(Box::new(CountingEntropy(1)));
        let first_len = 768 * 1024u32;
        let second_len = 512 * 1024u32;
        configure(&mut device, BUFFER, first_len, DESC_F_WRITE);
        write_descriptor(
            &device,
            1,
            BUFFER + u64::from(first_len),
            second_len,
            DESC_F_WRITE,
        );
        device.mem.wr_u16(AVAIL + 6, 1);
        device.mem.wr_u16(AVAIL + 2, 2);

        assert!(device.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(device.mem.rd_u16(USED + 2), 2);
        assert_eq!(device.mem.rd_u32(USED + 8), first_len);
        assert_eq!(device.mem.rd_u32(USED + 16), 256 * 1024);
    }

    #[test]
    fn refuses_illegal_queue_geometry_and_wrong_queue_notifications() {
        let mut device = device(Box::new(CountingEntropy(1)));
        configure(&mut device, BUFFER, 32, DESC_F_WRITE);
        device.write(R_QUEUE_NUM, 0x1_0000);
        assert!(!device.write(R_QUEUE_NOTIFY, 0));
        assert!(!device.write(R_QUEUE_NOTIFY, 1));
        assert_eq!(device.mem.rd_u16(USED + 2), 0);
    }

    #[test]
    fn reset_rewinds_device_owned_ring_cursors() {
        let mut device = device(Box::new(CountingEntropy(1)));
        configure(&mut device, BUFFER, 8, DESC_F_WRITE);
        assert!(device.write(R_QUEUE_NOTIFY, 0));
        assert_eq!(device.last_avail, 1);
        assert_eq!(device.next_used, 1);

        device.write(R_STATUS, 0);
        assert_eq!(device.last_avail, 0);
        assert_eq!(device.next_used, 0);
    }

    #[test]
    fn rng_device_state_roundtrips_without_entropy_bytes() {
        let mut source = device(Box::new(CountingEntropy(1)));
        source.device_features_sel = 1;
        source.status = 4;
        source.queue_num = 8;
        source.queue_ready = 1;
        source.desc = DESC;
        source.avail = AVAIL;
        source.used = USED;
        source.last_avail = 5;
        source.next_used = 6;
        source.interrupt_status = 1;
        let state = source.snapshot_state().unwrap();

        let mut target = device(Box::new(CountingEntropy(200)));
        target.restore_state(&state).unwrap();
        assert_eq!(target.device_features_sel, 1);
        assert_eq!(target.status, 4);
        assert_eq!(target.queue_num, 8);
        assert_eq!(target.queue_ready, 1);
        assert_eq!(
            (target.desc, target.avail, target.used),
            (DESC, AVAIL, USED)
        );
        assert_eq!((target.last_avail, target.next_used), (5, 6));
        assert_eq!(target.interrupt_status, 1);
    }
}
